mapper.select:
select
suggest.*,
users.name,
users.head_img
from suggest suggest
left join users users on suggest.user_id = users.id

    and suggest.id = #{id}
    and suggest.user_id = #{userId}
    and suggest.content like concat('%',#{content},'%')
    and suggest.admin_info = #{adminInfo}
    and suggest.status = #{status}
    and suggest.create_time = #{createTime}
    and users.name like concat('%',#{name},'%')
    and users.head_img = #{headImg}

order by id desc

    limit #{current},#{pageSize}

select count(*) from suggest suggest
left join users users on suggest.user_id = users.id

    and suggest.id = #{id}
    and suggest.user_id = #{userId}
    and suggest.content = #{content}
    and suggest.admin_info = #{adminInfo}
    and suggest.status = #{status}
    and suggest.create_time = #{createTime}
    and users.name like concat('%',#{name},'%')
    and users.head_img = #{headImg}
